@Test
    public void testAppendFixedWidthPadLeft_NullObject_WithDefaultNullText() {
        StrBuilder sb = new StrBuilder();
        // Default null text is usually "null"
        String nullText = sb.getNullText();
        int width = 10;
        sb.appendFixedWidthPadLeft(null, width, '*');

        String expected = "";
        int padLen = width - nullText.length();
        for(int i=0; i<padLen; i++) expected += '*';
        expected += nullText;

        assertEquals(expected, sb.toString());
    }

