    public void testCollatedIterator_NullHandling() {
        Comparator<Integer> comparator = Integer::compare;
        Iterator<Integer> it1 = Arrays.asList(1, 2).iterator();
        Iterator<Integer> it2 = Arrays.asList(3, 4).iterator();

        // Testing that the iterator itself handles nulls if the comparator allows
        // Or simply verifying that the method works with standard inputs.
        // Note: passing null as comparator or iterators would likely throw NPE, 
        // which is expected behavior for this utility.
        try {
            IteratorUtils.collatedIterator(null, it1, it2);
            fail("Should have thrown NPE");
        } catch (NullPointerException e) {
            // expected
        }
    }

