public static synchronized FastDateFormat getDateTimeInstance(int dateStyle, int timeStyle, TimeZone timeZone,
            Locale locale) {

        Object key = new Pair(new Integer(dateStyle), new Integer(timeStyle));
        if (timeZone != null) {
            key = new Pair(key, timeZone);
        }
        if (locale != null) {
            key = new Pair(key, locale);
        }

        FastDateFormat format = (FastDateFormat) cDateTimeInstanceCache.get(key);
        if (format == null) {
            if (locale == null) {
                locale = Locale.getDefault();
            }
            try {
                SimpleDateFormat formatter = (SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle,
                        locale);
                String pattern = formatter.toPattern();
                format = getInstance(pattern, timeZone, locale);
                cDateTimeInstanceCache.put(key, format);

            } catch (ClassCastException ex) {
                throw new IllegalArgumentException("No date time pattern for locale: " + locale);
            }
        }
        return format;
    }

test.method_source:
@Test
    public void testGetDateTimeInstance_AllParamsProvided() {
        int dateStyle = Calendar.LONG;
        int timeStyle = Calendar.SHORT;
        TimeZone tz = TimeZone.getTimeZone("GMT");
        Locale locale = Locale.US;

        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, locale);
        assertNotNull(format1);
        assertEquals(tz, format1.getTimeZone());
        assertEquals(locale, format1.getLocale());

        // Test caching mechanism: same params should return same instance
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, locale);
        assertNotSame("Should return cached instance", format1, format2); // Note: If the cache uses the same key, they should be same. 
        // Actually, based on the code: format = cDateTimeInstanceCache.get(key); if null... put.
